/**
 * Potion storage's own panel: tagging its potions, and dragging them onto tag tabs.
 * <p>
 * The store's rows cannot be dragged: the server marks them for clicks only, and a click on one acts the
 * moment the button goes down. So each potion's icon gets a draggable copy laid over it - in the store's
 * panel rather than its list, because every slot of the list carries the server's marks. The copy carries
 * the icon's own options, so a click opens the same doses menu (each pointed at the icon, the click the game
 * expects); held a moment and moved, it drags the potion's own icon. Dropped on a tag tab it tags the potion;
 * dropped anywhere else nothing happens. Not while the Potion Storage Customizer plugin is on, which rebuilds
 * the store's rows itself.
 * <p>
 * Every potion in the panel, copied or not, also gets the Bank Tags plugin's Edit-tags.
 */
@Slf4j
final class StorePanel
{
	/** A plugin that rebuilds potion storage's rows itself, which the draggable copies cannot live with. */
	private static final String CUSTOMIZER = "Potion Storage Customizer";
	private static final String EDIT_TAGS = "Edit-tags";
	/** A drag-parent depth of 2: the copy drags within its panel's parent, which holds the tag tabs. */
	private static final int DRAG_TWO_LEVELS_UP = 2 * WidgetConfig.DRAG;
	/** Client ticks a press is held before it becomes a drag. */
	private static final int HOLD_TO_DRAG_TICKS = 10;
	/** Pixels a press may wander before it counts as moved - a bank item's. */
	private static final int DRAG_DEAD_ZONE = 5;

	private final Client client;
	private final PotionStorageConfig config;
	private final PluginManager pluginManager;
	private final BankTagsBridge bankTags;
	private final Runnable relayout;

	// The copies, reused while the panel stands.
	private final List<Widget> copies = new ArrayList<>();
	private final Map<Integer, Integer> copyKind = new HashMap<>(); // a copy's child index -> its potion's kind
	/** The panel took a copy's slot for the server's: no copies this bank session. */
	private boolean refused;

	StorePanel(Client client, PotionStorageConfig config, PluginManager pluginManager, BankTagsBridge bankTags,
		Runnable relayout)
	{
		this.client = client;
		this.config = config;
		this.pluginManager = pluginManager;
		this.bankTags = bankTags;
		this.relayout = relayout;
	}

	/** The bank closed: its widgets, and the copies with them, are gone. */
	void reset()
	{
		copies.clear();
		copyKind.clear();
		refused = false;
	}

	/** The plugin is stopping: hide the copies, which outlive it while the bank stays open. */
	void remove()
	{
		copies.forEach(o -> o.setHidden(true));
		reset();
	}

	boolean isCopy(Widget w)
	{
		return w != null && w.getId() == InterfaceID.Bankmain.POTIONSTORE_CONTAINER && copyKind.containsKey(w.getIndex());
	}

	// ---- the copies ----

	/** Lay a copy over every potion's icon the panel shows, reusing the copies it has. */
	void refresh()
	{
		copyKind.clear();
		Widget layer = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_CONTAINER);
		Widget list = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		pruneCopies(layer);
		Widget[] rows = list == null ? null : list.getChildren();
		if (layer == null || rows == null || refused || !config.dragFromStore() || customizerActive())
		{
			hideCopiesFrom(0);
			return;
		}
		Widget dragArea = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		int used = 0;
		for (int kind = 0; PotionStore.iconChild(kind) < rows.length; kind++)
		{
			Widget row = rows[PotionStore.rowChild(kind)];
			Widget icon = rows[PotionStore.iconChild(kind)];
			if (row == null || icon == null || row.isSelfHidden() || icon.isSelfHidden() || icon.getItemId() <= 0 || row.getActions() == null)
			{
				continue;
			}
			Widget copy = copy(used, layer);
			if (copy == null)
			{
				return;
			}
			used++;
			dress(copy, icon, dragArea);
			copyKind.put(copy.getIndex(), kind);
		}
		hideCopiesFrom(used);
		sync();
	}

	/** Copies on a panel the game has rebuilt since went with it. */
	private void pruneCopies(Widget layer)
	{
		copies.removeIf(o -> layer == null || layer.getChild(o.getIndex()) != o);
	}

	/** The {@code n}th copy, made when there are not that many yet. Null when the panel will not take one. */
	private Widget copy(int n, Widget layer)
	{
		if (n < copies.size())
		{
			return copies.get(n);
		}
		Widget o = layer.createChild(-1, WidgetType.GRAPHIC);
		if (client.getWidgetConfig(o) != null)
		{
			// The server marks this slot too, which would make the copy as undraggable as the row.
			o.setHidden(true);
			refused = true;
			hideCopiesFrom(0);
			log.debug("potion storage's panel takes no draggable copies");
			return null;
		}
		copies.add(o);
		return o;
	}

	private static void dress(Widget o, Widget icon, Widget dragArea)
	{
		o.setOriginalWidth(icon.getOriginalWidth());
		o.setOriginalHeight(icon.getOriginalHeight());
		o.setItemId(icon.getItemId());
		o.setItemQuantity(icon.getItemQuantity());
		o.setItemQuantityMode(icon.getItemQuantityMode());
		o.setBorderType(icon.getBorderType());
		// The icon's own options - its doses - so a click opens the same menu it always did, and like the icon
		// it keeps the row's options from showing through.
		o.setName(icon.getName());
		o.clearActions();
		String[] actions = icon.getActions();
		for (int i = 0; actions != null && i < actions.length; i++)
		{
			if (actions[i] != null)
			{
				o.setAction(i, actions[i]);
			}
		}
		o.setHasListener(true);
		o.setNoClickThrough(true);
		o.setOnOpListener((JavaScriptCallback) ev ->
		{
		});
		// Dragged within the panel that holds both the store and the tag tabs - two levels up, as a bank item's
		// is - and only after a short hold, so a click is still a click.
		o.setClickMask(DRAG_TWO_LEVELS_UP);
		o.setDragDeadTime(HOLD_TO_DRAG_TICKS);
		o.setDragDeadZone(DRAG_DEAD_ZONE);
		o.setDragParent(dragArea);
	}

	private void hideCopiesFrom(int n)
	{
		for (int i = n; i < copies.size(); i++)
		{
			copies.get(i).setHidden(true);
		}
	}

	/** Keep each copy on its icon as the list scrolls, and hidden while its icon is scrolled out of view. */
	void sync()
	{
		if (copyKind.isEmpty())
		{
			return;
		}
		Widget layer = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_CONTAINER);
		Widget list = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		if (layer == null || list == null || layer.isHidden() || isCopy(client.getDraggedWidget()))
		{
			return;
		}
		Point origin = layer.getCanvasLocation();
		int listTop = list.getCanvasLocation().getY();
		int listBottom = listTop + list.getHeight();
		for (Widget o : copies)
		{
			Integer kind = copyKind.get(o.getIndex());
			if (kind == null)
			{
				continue;
			}
			Widget icon = list.getChild(PotionStore.iconChild(kind));
			if (icon == null || icon.isSelfHidden())
			{
				o.setHidden(true);
				continue;
			}
			Point at = icon.getCanvasLocation();
			int x = at.getX() - origin.getX();
			int y = at.getY() - origin.getY();
			boolean visible = at.getY() + icon.getHeight() > listTop && at.getY() < listBottom;
			if (o.getOriginalX() != x || o.getOriginalY() != y || o.isSelfHidden() == visible)
			{
				o.setOriginalX(x);
				o.setOriginalY(y);
				o.setHidden(!visible);
				o.revalidate();
			}
		}
	}

	// ---- clicks, drops and menus ----

	/** A click on a copy is a click on the icon under it; the server never hears of the copy itself. */
	void click(MenuOptionClicked e)
	{
		if (!isWidgetOp(e.getMenuAction()))
		{
			return;
		}
		Integer kind = copyKind.get(e.getParam0());
		if (kind == null)
		{
			// One of this plugin's copies that no longer stands for a potion: nothing the server knows of.
			if (copies.contains(e.getWidget()))
			{
				e.consume();
			}
			return;
		}
		MenuEntry m = e.getMenuEntry();
		m.setParam1(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		m.setParam0(PotionStore.iconChild(kind));
	}

	/** A copy dropped on a tag tab tags its potion; shift tags all of its doses, as for a bank item. */
	void drop(Widget src)
	{
		Widget dst = client.getDraggedOnWidget();
		if (client.isDraggingWidget() && dst != null && BankTagsBridge.isTagTab(dst))
		{
			String tag = Text.removeTags(dst.getName());
			bankTags.addTag(src.getItemId(), tag, client.isKeyPressed(KeyCode.KC_SHIFT));
			log.debug("tagged {} '{}' from potion storage", src.getItemId(), tag);
		}
		// Nothing about this drag is the server's business.
		client.setDraggedOnWidget(null);
	}

	/**
	 * Over a potion's icon only the copy's options belong in the menu, as only the icon's did before: drop
	 * whatever of the icon's or the row's still came through - theirs, and any a plugin added to them.
	 */
	void dedupeMenu()
	{
		if (copyKind.isEmpty() || client.isMenuOpen())
		{
			return;
		}
		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		Set<Integer> covered = new HashSet<>();
		for (MenuEntry m : entries)
		{
			Integer kind = m.getParam1() == InterfaceID.Bankmain.POTIONSTORE_CONTAINER ? copyKind.get(m.getParam0()) : null;
			if (kind != null)
			{
				covered.add(PotionStore.rowChild(kind));
				covered.add(PotionStore.iconChild(kind));
			}
		}
		if (covered.isEmpty())
		{
			return;
		}
		MenuEntry[] kept = Arrays.stream(entries)
			.filter(m -> !(m.getParam1() == InterfaceID.Bankmain.POTIONSTORE_ITEMS && covered.contains(m.getParam0())))
			.toArray(MenuEntry[]::new);
		if (kept.length != entries.length)
		{
			menu.setMenuEntries(kept);
		}
	}

	/**
	 * Edit-tags on a potion in the store, the Bank Tags plugin's own option for a bank item: on its row's menu,
	 * and on its copy's.
	 */
	void addEditTags(MenuEntryAdded e)
	{
		Widget icon = editableIcon(e);
		if (icon == null || icon.getItemId() <= 0 || !bankTags.active())
		{
			return;
		}
		int itemId = icon.getItemId();
		long count = bankTags.shownTagCount(itemId);
		client.getMenu().createMenuEntry(-2)
			.setParam0(e.getActionParam0())
			.setParam1(e.getActionParam1())
			.setTarget(e.getTarget())
			.setOption(EDIT_TAGS + (count > 0 ? " (" + count + ")" : ""))
			.setType(MenuAction.RUNELITE)
			.setIdentifier(e.getIdentifier())
			.setItemId(itemId)
			.onClick(m -> bankTags.editTags(itemId, client.getItemDefinition(itemId).getName(), relayout));
	}

	/**
	 * The potion icon a new menu entry is the last of: a row's last option is its Withdraw-All-but-1, and a
	 * copy's is whichever came last - one Edit-tags per menu.
	 */
	private Widget editableIcon(MenuEntryAdded e)
	{
		int child = e.getActionParam0();
		if (e.getActionParam1() == InterfaceID.Bankmain.POTIONSTORE_ITEMS)
		{
			if (!BankWidgets.WITHDRAW_ALL_BUT_ONE.equals(e.getOption()) || child % PotionStore.COMPONENTS_PER_POTION != 0)
			{
				return null;
			}
			Widget list = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
			return list == null ? null : list.getChild(PotionStore.iconChild(child / PotionStore.COMPONENTS_PER_POTION));
		}
		if (e.getActionParam1() == InterfaceID.Bankmain.POTIONSTORE_CONTAINER && copyKind.containsKey(child)
			&& Arrays.stream(client.getMenu().getMenuEntries()).noneMatch(m -> m.getParam1() == e.getActionParam1()
				&& m.getParam0() == child && m.getOption().startsWith(EDIT_TAGS)))
		{
			Widget layer = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_CONTAINER);
			return layer == null ? null : layer.getChild(child);
		}
		return null;
	}

	private boolean customizerActive()
	{
		return BankTagsBridge.findActive(pluginManager, p -> CUSTOMIZER.equals(p.getName())) != null;
	}
}

package com.potionstorage;

import com.potionstorage.BankArrangement.Drop;
import com.potionstorage.BankArrangement.Entry;
import com.potionstorage.BankArrangement.Pos;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The order the bank is drawn in once stored potions stand among real items. Real ids are small numbers,
 * stored keys are 9xx, and {@link #show} renders a section as {@code 1 2 p900 3} so a failure reads like the bank.
 */
public class BankArrangementTest
{
	private static String show(Map<Integer, List<Entry>> drawn, int s)
	{
		return drawn.getOrDefault(s, Collections.emptyList()).stream().map(Entry::toString).collect(Collectors.joining(" "));
	}

	private static Map<Integer, List<Integer>> bank(Object... sectionsAndIds)
	{
		Map<Integer, List<Integer>> m = new LinkedHashMap<>();
		for (int i = 0; i < sectionsAndIds.length; i += 2)
		{
			m.put((Integer) sectionsAndIds[i], Arrays.asList((Integer[]) sectionsAndIds[i + 1]));
		}
		return m;
	}

	private static Integer[] ids(Integer... ids)
	{
		return ids;
	}

	private static List<Integer> stored(Integer... keys)
	{
		return Arrays.asList(keys);
	}

	private static Set<Integer> sections(Integer... sections)
	{
		return new HashSet<>(Arrays.asList(sections));
	}

	/** A bank whose tabs are the ones it has items in, with no earlier server order to follow. */
	private static BankArrangement.Resolved resolve(BankArrangement a, Map<Integer, List<Integer>> reals, List<Integer> stored)
	{
		Set<Integer> existing = new HashSet<>(reals.keySet());
		existing.add(BankArrangement.MAIN);
		return a.resolve(reals, null, stored, existing);
	}

	private static Map<Integer, List<Entry>> draw(BankArrangement a, Map<Integer, List<Integer>> reals, List<Integer> stored)
	{
		return resolve(a, reals, stored).drawn;
	}

	@Test
	public void freshBankIsServerOrderWithStoredStacksAtTheEndOfTheUntabbedPart()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2, 3), 1, ids(4, 5));
		BankArrangement.Resolved r = resolve(a, reals, stored(900, 901));
		assertTrue(r.changed);
		assertEquals("1 2 3 p900 p901", show(r.drawn, 0));
		assertEquals("4 5", show(r.drawn, 1));
		assertFalse(resolve(a, reals, stored(900, 901)).changed);
	}

	@Test
	public void insertModePutsTheDraggedEntryInTheTargetsPlace()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2, 3));
		Map<Integer, List<Entry>> d = draw(a, reals, stored(900));
		a.move(d, new Pos(0, 3), new Pos(0, 1), Drop.INSERT);
		d = draw(a, reals, stored(900));
		assertEquals("1 p900 2 3", show(d, 0));
		a.move(d, new Pos(0, 0), new Pos(0, 2), Drop.INSERT);
		assertEquals("p900 2 1 3", show(draw(a, reals, stored(900)), 0));
	}

	@Test
	public void swapModeTradesTwoPlaces()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2, 3, 4));
		Map<Integer, List<Entry>> d = draw(a, reals, stored(900));
		a.move(d, new Pos(0, 4), new Pos(0, 1), Drop.SWAP);
		assertEquals("1 p900 3 4 2", show(draw(a, reals, stored(900)), 0));
	}

	@Test
	public void storedStackMovesIntoAnotherTabAndSurvivesASave()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2), 1, ids(3, 4));
		Map<Integer, List<Entry>> d = draw(a, reals, stored(900));
		a.move(d, new Pos(0, 2), new Pos(1, 1), Drop.INSERT);
		Map<Integer, List<Entry>> after = draw(a, reals, stored(900));
		assertEquals("1 2", show(after, 0));
		assertEquals("3 p900 4", show(after, 1));
		assertEquals("3 p900 4", show(draw(BankArrangement.decode(a.encode()), reals, stored(900)), 1));
	}

	@Test
	public void depositLandsAtTheEndOfItsTabAfterStoredStacks()
	{
		BankArrangement a = new BankArrangement();
		assertEquals("1 2 p900", show(draw(a, bank(0, ids(1, 2)), stored(900)), 0));
		assertEquals("1 2 p900 7", show(draw(a, bank(0, ids(1, 2, 7)), stored(900)), 0));
	}

	@Test
	public void potionTheStoreRunsOutOfKeepsItsPlace()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2, 3));
		Map<Integer, List<Entry>> d = draw(a, reals, stored(900));
		a.move(d, new Pos(0, 3), new Pos(0, 1), Drop.INSERT);
		assertEquals("1 2 3", show(draw(a, reals, stored()), 0));
		assertEquals("1 p900 2 3", show(draw(a, reals, stored(900)), 0));
	}

	@Test
	public void ghostKeepsItsPlaceThroughARearrange()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2, 3));
		Map<Integer, List<Entry>> d = draw(a, reals, stored(900, 901));
		a.move(d, new Pos(0, 4), new Pos(0, 1), Drop.INSERT); // 1 p901 2 3 p900
		d = draw(a, reals, stored(900)); // p901 out of stock: 1 2 3 p900
		a.move(d, new Pos(0, 0), new Pos(0, 2), Drop.INSERT); // drawn 2 3 1 p900
		assertEquals("2 3 1 p900", show(draw(a, reals, stored(900)), 0));
		assertEquals("2 3 1 p901 p900", show(draw(a, reals, stored(900, 901)), 0));
	}

	@Test
	public void realItemMovedToAnotherTabLeavesItsOldTabsOrder()
	{
		BankArrangement a = new BankArrangement();
		draw(a, bank(0, ids(1, 2), 1, ids(3)), stored());
		Map<Integer, List<Entry>> moved = draw(a, bank(0, ids(2), 1, ids(3, 1)), stored());
		assertEquals("2", show(moved, 0));
		assertEquals("3 1", show(moved, 1));
		assertEquals("0=2;1=3,1", a.encode());
	}

	@Test
	public void deletingATabRenumbersTheOnesAfterIt()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> before = bank(0, ids(1), 1, ids(2), 2, ids(3, 4), 3, ids(5, 6));
		Map<Integer, List<Entry>> d = draw(a, before, stored(900, 901));
		a.moveToEnd(d, new Pos(0, 1), 2);
		d = draw(a, before, stored(900, 901));
		a.moveToEnd(d, new Pos(0, 1), 3);
		d = draw(a, before, stored(900, 901));
		a.move(d, new Pos(3, 2), new Pos(3, 0), Drop.INSERT);
		BankArrangement.Resolved r = a.resolve(bank(0, ids(1, 2), 1, ids(3, 4), 2, ids(5, 6)), null, stored(900, 901),
			sections(0, 1, 2));
		assertEquals("1 2", show(r.drawn, 0));
		assertEquals("3 4 p900", show(r.drawn, 1));
		assertEquals("p901 5 6", show(r.drawn, 2));
	}

	@Test
	public void resolvingACopyAgainstAHalfUpdatedBankLeavesTheSavedOrderAlone()
	{
		// A build that saw the new item order with the old tab sizes: tab 7's only item read as untabbed and
		// tab 6's edge item as tab 7's. Learned, that merged the whole potions tab into tab 6.
		BankArrangement a = BankArrangement.decode("0=995;6=1,2,3;7=229,p900,p901");
		a.copy().resolve(bank(0, ids(995, 229), 6, ids(1, 2), 7, ids(3)), null, stored(900, 901), sections(0, 6, 7));
		assertEquals("0=995;6=1,2,3;7=229,p900,p901", a.encode());
		BankArrangement.Resolved settled = a.resolve(bank(0, ids(995), 6, ids(1, 2, 3), 7, ids(229)), null, stored(900, 901),
			sections(0, 6, 7));
		assertEquals("229 p900 p901", show(settled.drawn, 7));
	}

	@Test
	public void storedStackInATabThatNoLongerExistsGoesHome()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Entry>> d = draw(a, bank(0, ids(1), 4, ids(7)), stored(900));
		a.moveToEnd(d, new Pos(0, 1), 4);
		BankArrangement.Resolved r = a.resolve(bank(0, ids(1, 7)), null, stored(900), sections(0));
		assertEquals("1 7 p900", show(r.drawn, 0));
	}

	@Test
	public void encodingRoundTrips()
	{
		BankArrangement a = BankArrangement.decode("0=1,2,p900;3=5,p901,6");
		assertEquals("0=1,2,p900;3=5,p901,6", a.encode());
		assertEquals("5 p901 6", show(draw(a, bank(0, ids(1, 2), 3, ids(5, 6)), stored(900, 901)), 3));
		assertEquals("", BankArrangement.decode(null).encode());
		assertEquals("0=1", BankArrangement.decode("0=1,,x;bad").encode());
	}

	@Test
	public void tabEmptiedIntoAnotherKeepsThatTabsOwnStacks()
	{
		// Tab 5's last item dropped into tab 4: tab 5 is gone, and tab 4 - which kept its own items - is not
		// a renumbered tab 5. Its stored stack stays put; tab 5's goes to the untabbed part.
		BankArrangement a = BankArrangement.decode("0=1;4=10,11,p900;5=20,p901");
		BankArrangement.Resolved r = a.resolve(bank(0, ids(1), 4, ids(10, 11, 20)), null, stored(900, 901), sections(0, 1, 2, 3, 4));
		assertEquals("10 11 p900 20", show(r.drawn, 4));
		assertEquals("1 p901", show(r.drawn, 0));
	}

	@Test
	public void tabEmptiedIntoAnotherKeepsThatTabsGhosts()
	{
		BankArrangement a = BankArrangement.decode("0=1;4=11,12,10,p900;5=20");
		a.resolve(bank(0, ids(1), 4, ids(10, 11, 20)), null, stored(900), sections(0, 1, 2, 3, 4));
		assertEquals("0=1;4=11,12,20,10,p900", a.encode());
	}

	@Test
	public void reorderMadeOutOfSightIsFollowed()
	{
		// The server swapped 1 and 2 - in a search, with the plugin off, on another device.
		BankArrangement a = BankArrangement.decode("0=1,2,3,p900");
		BankArrangement.Resolved r = a.resolve(bank(0, ids(2, 1, 3)), bank(0, ids(1, 2, 3)), stored(900), sections(0));
		assertTrue(r.changed);
		assertEquals("2 1 3 p900", show(r.drawn, 0));
	}

	@Test
	public void itemMovedToTheEndOutOfSightGoesAfterItsNewNeighbour()
	{
		BankArrangement a = BankArrangement.decode("0=1,p900,2,3");
		BankArrangement.Resolved r = a.resolve(bank(0, ids(2, 3, 1)), bank(0, ids(1, 2, 3)), stored(900), sections(0));
		assertEquals("p900 2 3 1", show(r.drawn, 0));
	}

	@Test
	public void moveTheOrderAlreadyHasIsLeftAlone()
	{
		// The plugin followed the drag itself; the server's version of it changes nothing more.
		BankArrangement a = BankArrangement.decode("0=2,1,p900,3");
		BankArrangement.Resolved r = a.resolve(bank(0, ids(2, 1, 3)), bank(0, ids(1, 2, 3)), stored(900), sections(0));
		assertFalse(r.changed);
		assertEquals("2 1 p900 3", show(r.drawn, 0));
	}

	@Test
	public void sameServerOrderFollowsNothing()
	{
		BankArrangement a = BankArrangement.decode("0=3,p900,1,2");
		BankArrangement.Resolved r = a.resolve(bank(0, ids(1, 2, 3)), bank(0, ids(1, 2, 3)), stored(900), sections(0));
		assertFalse(r.changed);
		assertEquals("3 p900 1 2", show(r.drawn, 0));
	}

	@Test
	public void moveOutsideWhatIsDrawnChangesNothing()
	{
		BankArrangement a = BankArrangement.decode("0=1,2,p900");
		Map<Integer, List<Entry>> d = draw(a, bank(0, ids(1, 2)), stored(900));
		a.move(d, new Pos(0, 5), new Pos(0, 0), Drop.INSERT);
		a.move(d, new Pos(3, 0), new Pos(0, 0), Drop.INSERT);
		assertEquals("0=1,2,p900", a.encode());
	}

	@Test
	public void moveToEndOfASectionWithNothingDrawnStartsIt()
	{
		BankArrangement a = BankArrangement.decode("0=1,2,p900");
		Map<Integer, List<Entry>> d = draw(a, bank(0, ids(1, 2), 3, ids(7)), stored(900));
		a.moveToEnd(d, new Pos(0, 2), 2);
		assertEquals("0=1,2;2=p900;3=7", a.encode());
	}

	@Test
	public void serverOrderRoundTrips()
	{
		Map<Integer, List<Integer>> order = bank(0, ids(995, 989), 3, ids(1127));
		assertEquals("0=995,989;3=1127", BankArrangement.encodeOrder(order));
		assertEquals(order, BankArrangement.decodeOrder("0=995,989;3=1127"));
		assertEquals(null, BankArrangement.decodeOrder(null));
	}

	@Test
	public void inFrontPutsTheDraggedEntryBeforeTheTargetEitherWay()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2, 3));
		Map<Integer, List<Entry>> d = draw(a, reals, stored(900));
		a.move(d, new Pos(0, 3), new Pos(0, 1), Drop.IN_FRONT); // backward: the same as the bank's insert
		d = draw(a, reals, stored(900));
		assertEquals("1 p900 2 3", show(d, 0));
		a.move(d, new Pos(0, 0), new Pos(0, 3), Drop.IN_FRONT); // forward: in front of 3, where insert goes after it
		assertEquals("p900 2 1 3", show(draw(a, reals, stored(900)), 0));
	}

	@Test
	public void inFrontIntoAnotherTab()
	{
		BankArrangement a = new BankArrangement();
		Map<Integer, List<Integer>> reals = bank(0, ids(1, 2), 1, ids(3, 4));
		Map<Integer, List<Entry>> d = draw(a, reals, stored(900));
		a.move(d, new Pos(0, 2), new Pos(1, 1), Drop.IN_FRONT);
		Map<Integer, List<Entry>> after = draw(a, reals, stored(900));
		assertEquals("1 2", show(after, 0));
		assertEquals("3 p900 4", show(after, 1));
	}

	@Test
	public void droppingAStackOnItselfChangesNothing()
	{
		BankArrangement a = BankArrangement.decode("0=1,p900,2");
		Map<Integer, List<Entry>> d = draw(a, bank(0, ids(1, 2)), stored(900));
		for (Drop how : Drop.values())
		{
			a.move(d, new Pos(0, 1), new Pos(0, 1), how);
		}
		assertEquals("0=1,p900,2", a.encode());
	}
}

package com.potionstorage;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/** A stored stack's left-click option reads like the bank's own, whatever its quantity setting. */
public class BankViewTest
{
	@Test
	public void defaultWithdrawFollowsTheBanksQuantitySetting()
	{
		assertEquals("1", BankView.defaultWithdraw(0, 0));
		assertEquals("5", BankView.defaultWithdraw(1, 0));
		assertEquals("10", BankView.defaultWithdraw(2, 0));
		assertEquals("14", BankView.defaultWithdraw(3, 14));
		assertEquals("1", BankView.defaultWithdraw(3, 0));
		assertEquals("All", BankView.defaultWithdraw(4, 0));
	}
}

